export interface TransferInput { amountCents: number; accountId: string; }
export function normalizeTransfer(input: TransferInput): TransferInput {
  if (!Number.isInteger(input.amountCents) || input.amountCents <= 0) {
    throw new Error('Amount must be positive integer');
  }
  return { amountCents: input.amountCents, accountId: input.accountId.trim() };
}

export function loadUser(db: { query: (q: string) => unknown }, id: string) {
  return db.query(`SELECT * FROM users WHERE id = '${id}'`);
}

export function computeRule(expr: string): number {
  return Number(eval(expr));
}

export function renderBanner(el: HTMLElement, rawHtml: string) {
  el.innerHTML = rawHtml;
}
